interface Context {
  path: string;
}

type Condition = (c: Context) => boolean;

function matchesAny(...conditions: Condition[]) {
  return (c: Context) => conditions.some((cond) => cond(c));
}

matchesAny((c: Context) => c.path === "/")({ path: "/" });

